"""Extracted engine domain functions; shared-namespace installer."""

SOURCE = 'def _save_task_plan():\n    """Persist the current task plan to .shai/task.json."""\n    try:\n        TASK_FILE.parent.mkdir(parents=True, exist_ok=True)\n        temporary = TASK_FILE.with_name(TASK_FILE.name + ".tmp")\n        with temporary.open("w", encoding="utf-8") as handle:\n            json.dump({"tasks": TASK_PLAN}, handle, indent=2, ensure_ascii=False)\n            handle.write("\\n")\n        temporary.replace(TASK_FILE)\n    except OSError as error:\n        LOGGER.warning("Failed to save task plan: %s", error)\n\ndef _pending_task_plan_items():\n    """Return unfinished task titles from the current visible task plan."""\n    return [\n        item.get("title", "(untitled task)")\n        for item in TASK_PLAN\n        if isinstance(item, dict)\n        and item.get("status") in ("pending", "in_progress")\n    ]\n\ndef _continue_incomplete_plan(history, continuation_count, finish_reason):\n    """Ask the model to continue when it emits narration but leaves planned work.\n\n    This is deliberately bounded: it repairs the common \'I\'ll do that next\'\n    text-only response without allowing an unbounded self-prompting loop.\n    """\n    pending = _pending_task_plan_items()\n    if not pending or continuation_count >= MAX_PLAN_CONTINUATIONS:\n        return False\n    LOGGER.warning(\n        "Model returned without tool calls while task plan is incomplete; "\n        "continuing %d/%d finish_reason=%s pending=%r",\n        continuation_count + 1, MAX_PLAN_CONTINUATIONS, finish_reason, pending\n    )\n    history.append({\n        "role": "user",\n        "content": (\n            "Continue executing the existing task plan now. Do not merely describe "\n            "what you intend to do. Use the available tools to complete the pending "\n            "items, verify the results, and mark each task completed or blocked. "\n            "If you genuinely cannot proceed, explain the blocker. Pending items: "\n            + "; ".join(pending)\n        )\n    })\n    return True\n\ndef _load_task_plan():\n    """Load the task plan from .shai/task.json if it exists."""\n    global TASK_PLAN\n    try:\n        if TASK_FILE.exists():\n            with TASK_FILE.open("r", encoding="utf-8") as handle:\n                data = json.load(handle)\n                if isinstance(data, dict) and isinstance(data.get("tasks"), list):\n                    TASK_PLAN = data["tasks"]\n                    STATUS.update(task_plan=TASK_PLAN)\n    except (OSError, ValueError) as error:\n        LOGGER.warning("Failed to load task plan: %s", error)\n\ndef update_task_plan(steps):\n    """Set the visible in-memory task checklist for the current agent task."""\n    global TASK_PLAN\n    if not isinstance(steps, list) or not steps:\n        return "steps must be a non-empty array of task objects."\n    updated = []\n    for item in steps:\n        if not isinstance(item, dict):\n            return "Each step must be an object with title and status."\n        title = item.get("title")\n        status = item.get("status", "pending")\n        if not isinstance(title, str) or not title.strip():\n            return "Each task step needs a non-empty title."\n        if status not in ("pending", "in_progress", "completed", "blocked"):\n            return "Invalid task status for {!r}.".format(title)\n        updated.append({"title": title.strip(), "status": status})\n    TASK_PLAN = updated\n    STATUS.update(task_plan=TASK_PLAN)\n    _save_task_plan()\n    return "Task plan updated:\\n" + "\\n".join(\n        "[{}] {}".format(\n            {"pending": " ", "in_progress": "~", "completed": "x", "blocked": "!"}[item["status"]],\n            item["title"]\n        ) for item in TASK_PLAN\n    )'

def install(namespace):
    exec(compile(SOURCE, __file__, "exec"), namespace)
